"""Qdrant vector database client with collection management for code_entities and dossier_findings."""

from typing import Any, Optional

from qdrant_client import QdrantClient
from qdrant_client.models import (
    Distance,
    FieldCondition,
    Filter,
    MatchValue,
    PointStruct,
    VectorParams,
)

from src.config import get_settings

# Embedding dimension — all-MiniLM-L6-v2 produces 384-dim vectors
EMBEDDING_DIM = 384

COLLECTION_CODE_ENTITIES = "code_entities"
COLLECTION_DOSSIER_FINDINGS = "dossier_findings"

_client: Optional[QdrantClient] = None


def get_client() -> QdrantClient:
    global _client
    if _client is None:
        settings = get_settings()
        _client = QdrantClient(url=settings.qdrant_url, api_key=settings.qdrant_api_key or None)
    return _client


def ensure_collections() -> None:
    """Create required collections if they do not exist."""
    client = get_client()
    existing = {c.name for c in client.get_collections().collections}

    for collection_name in (COLLECTION_CODE_ENTITIES, COLLECTION_DOSSIER_FINDINGS):
        if collection_name not in existing:
            client.create_collection(
                collection_name=collection_name,
                vectors_config=VectorParams(size=EMBEDDING_DIM, distance=Distance.COSINE),
            )


def upsert(
    collection_name: str,
    point_id: str,
    vector: list[float],
    payload: dict[str, Any],
) -> None:
    """Insert or update a single vector point."""
    get_client().upsert(
        collection_name=collection_name,
        points=[PointStruct(id=_stable_id(point_id), vector=vector, payload=payload)],
    )


def search(
    collection_name: str,
    query_vector: list[float],
    limit: int = 10,
    filter_by: Optional[dict[str, Any]] = None,
    score_threshold: float = 0.0,
) -> list[dict[str, Any]]:
    """Semantic similarity search with optional metadata filtering.

    Args:
        filter_by: Dict of field→value pairs applied as AND conditions.
                   Example: {"module_id": "abc123", "severity": "high"}
    """
    qdrant_filter = None
    if filter_by:
        qdrant_filter = Filter(
            must=[
                FieldCondition(key=k, match=MatchValue(value=v))
                for k, v in filter_by.items()
            ]
        )

    results = get_client().search(
        collection_name=collection_name,
        query_vector=query_vector,
        limit=limit,
        query_filter=qdrant_filter,
        score_threshold=score_threshold,
    )
    return [{"id": str(r.id), "score": r.score, **r.payload} for r in results]


def delete_by_filter(collection_name: str, filter_by: dict[str, Any]) -> None:
    """Delete points matching given metadata filter."""
    from qdrant_client.models import FilterSelector

    qdrant_filter = Filter(
        must=[
            FieldCondition(key=k, match=MatchValue(value=v))
            for k, v in filter_by.items()
        ]
    )
    get_client().delete(
        collection_name=collection_name,
        points_selector=FilterSelector(filter=qdrant_filter),
    )


def _stable_id(uuid_str: str) -> str:
    """Return point ID suitable for Qdrant (hex string → keeps UUID format)."""
    return uuid_str.replace("-", "")

