.docsLayout {
  display: grid;
  grid-template-columns: 300px 1fr 280px;
  max-width: 1800px;
  margin: 0 auto;
  min-height: 100vh;
  gap: 24px;
  padding: 24px;
}

.sidebarLeft {
  position: sticky;
  top: 24px;
  height: calc(100vh - 48px);
  overflow-y: auto;
  padding: 32px;
