  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.sidebarRight {
  position: sticky;
  top: 24px;
  height: calc(100vh - 48px);
  overflow-y: auto;
  padding: 28px;
  scrollbar-width: thin;
  scrollbar-color: rgba(139, 92, 246, 0.3) transparent;
}

