  sections: NavSection[];
  repoName?: string;
  repoOwner?: string;
  repoHref?: string;
}

export function Sidebar({ sections, repoName, repoOwner, repoHref = '/' }: SidebarProps) {
  const pathname = usePathname();

  return (
    <nav className={styles.sidebarNav}>
